Снимок показывает существующий проверочный код проекта, переносы длинных строк изменены для слайда. Указатель skeletal получен dynamic_cast в цикле по scene.GetComponents(); continue относится к этому циклу. Не полный отдельный translation unit.
Код на снимке:
const auto slots = skeletal->GetMaterialSlots();
if (slots.empty()) continue;
const uint32_t sourceId = slots.begin()->first;
const std::string originalPath = slots.begin()->second;
const std::string material =
    "/Game/Models/CesiumMan/Materials/Material_0.mat";
const bool slotSet =
    skeletal->SetMaterialSlot(sourceId, material);
const bool unknownSlotSet =
    skeletal->SetMaterialSlot(UINT32_MAX, material);
const bool overrideSet = skeletal->SetMaterialAsset(material);
const std::string overridePath = skeletal->GetMaterialAsset();
const bool overrideCleared = skeletal->SetMaterialAsset("");

