Фрагмент с переносами строк для чтения. previous — статический uint64_t, log — открытый std::ofstream, полный код рядом. Пример включается CURIOUS_CITY_FRAME_STATS=1 и CURIOUS_CITY_LOG=<path>.
Код на снимке:
const auto& frame = GetCompletedFrameStats();
if (frame.valid && frame.frameIndex != previous) {
    previous = frame.frameIndex;
    log << "completed_frame valid=true index="
        << frame.frameIndex
        << " draw_calls=" << frame.counters.DrawCalls
        << " visible=" << frame.counters.VisibleObjects
        << " culled=" << frame.counters.CulledObjects
        << '\n';
}

